      price: 99.99,
      image: 'assets/images/products/garden-bloom.jpg'
    }
  ];

  bestSellers = [
    {
      id: 9,
      name: 'Royal Oud',
      category: 'Perfume',
      price: 129.99,
      image: 'assets/images/products/royal-oud.jpg'
    },
    {
      id: 10,
      name: 'Amber Gold',
      category: 'Perfume',
      price: 119.99,
      image: 'assets/images/products/amber-gold.jpg'
    },
    {
      id: 11,
      name: 'Citrus Zest',
      category: 'Perfume',
      price: 89.99,
      image: 'assets/images/products/citrus-zest.jpg'
    },
    {
      id: 12,
      name: 'Vanilla Dream',
      category: 'Perfume',
      price: 99.99,
      image: 'assets/images/products/vanilla-dream.jpg'
    }
  ];
}
